// Security headers for every Worker response (/api/*, /auth/*). Static assets get theirs from
// web/public/_headers, which Cloudflare does not apply to responses generated by the Worker.
import { createMiddleware } from "hono/factory";

/** JSON, redirects and the receipt file stream: nothing here should run, load or be framed. */
export const WORKER_CSP = "default-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'; sandbox";

const HEADERS: Record<string, string> = {
  "Content-Security-Policy": WORKER_CSP,
  "X-Frame-Options": "DENY",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "no-referrer",
  "Strict-Transport-Security": "max-age=31536000",
};

export const securityHeaders = createMiddleware(async (c, next) => {
  await next();
  for (const [name, value] of Object.entries(HEADERS)) c.header(name, value);
});
